  protected ShadowModule createModule(String name) {
    ShadowModule module = new ShadowModule(name);
    repository.registerModule(module, moduleOwner);
    SetSequence.fromSet(createdModules).addElement(module);
    return module;
  }

  protected ShadowModel createModel(ShadowModule parent, String name) {
    ShadowModel model = new ShadowModel(parent, name);
    parent.registerModel(model);
    return model;
  }

  protected void removeModule(ShadowModule module) {
    if (module.getRepository() == null) {
      return;
    }
    repository.unregisterModule(module, moduleOwner);
    SetSequence.fromSet(createdModules).removeElement(module);
  }

  protected void removeModel(SModel model) {
    SModule module = model.getModule();
    if (module == null) {
      return;
    }
    if (module instanceof ShadowModule) {
      ((ShadowModule) module).unregisterModel((SModelBase) model);
    } else {
      new ModelDeleteHelper(model).delete();
    }
  }

